import{_ as n,C as p,o as e,c as r,a3 as s,b as l,w as a,a as d,E as h,a4 as o}from"./chunks/framework.CWYzGJW1.js";const b=JSON.parse('{"title":"P3 會議記錄摘要","description":"里程碑 1 (M0 至 M2) 加上一個可地端執行的語音轉文字程式, 就能把會議錄音整理成摘要, 決議與待辦清單.","frontmatter":{"description":"里程碑 1 (M0 至 M2) 加上一個可地端執行的語音轉文字程式, 就能把會議錄音整理成摘要, 決議與待辦清單."},"headers":[],"relativePath":"examples/p3-meeting-notes.md","filePath":"examples/p3-meeting-notes.md","lastUpdated":1793060541000}'),E={name:"examples/p3-meeting-notes.md"};function c(k,t,g,C,A,m){const i=p("Mermaid");return e(),r("div",null,[t[1]||(t[1]=s('<h1 id="p3-會議記錄摘要" tabindex="-1">P3 會議記錄摘要 <a class="header-anchor" href="#p3-會議記錄摘要" aria-label="Permalink to &quot;P3 會議記錄摘要&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本章屬性</p><ul><li>等級: ○ 依情境</li><li>狀態: 可閱讀 (部分資料待核對)</li><li>資料基準日: 2026-10-26</li><li>待查證: whisper.cpp 與 OpenCC 指令依官方 README 整理, 未實機驗證; Whisper 對台灣華語, 中英夾雜與專有名詞的辨識準確度無公開基準; Open WebUI 內建語音轉文字是否支援直接上傳錄音檔, 官方文件未說明; 長逐字稿的分段長度建議屬推論; 文中的類比為整理者所寫, 不代表技術上完全等同</li></ul></div><p><strong>結論</strong>: 里程碑 1 (M0 至 M2) 加上一個可地端執行的語音轉文字程式, 就能把會議錄音整理成摘要, 決議與待辦清單. 本頁以 whisper.cpp 搭配 OpenAI Whisper 模型為例: Whisper 是把語音辨識成文字的模型, whisper.cpp 是在一般電腦上執行這個模型的程式 (兩者皆為 MIT 授權), 錄音與逐字稿都不離開本機. 模型產生的摘要一律由記錄者核對後才寄給與會者, 尤其是決議, 負責人與期限.</p><p><strong>對象</strong>: 個人. <strong>需要的模組</strong>: M1, M2.</p><div class="tip custom-block"><p class="custom-block-title">本頁常見名詞</p><table tabindex="0"><thead><tr><th>詞</th><th>意思</th></tr></thead><tbody><tr><td>語音轉文字 (speech-to-text)</td><td>把錄音轉成文字的程式; 本頁用 Whisper 模型</td></tr><tr><td>whisper.cpp</td><td>用 C/C++ 重新實作的 Whisper 執行程式, 可在一般電腦上離線轉錄</td></tr><tr><td>ffmpeg</td><td>常用的影音格式轉換工具</td></tr><tr><td>終端機 (terminal)</td><td>以文字輸入指令操作電腦的視窗; 本頁的 <code>bash</code> 區塊都在這裡執行</td></tr><tr><td>OpenCC</td><td>開源的簡繁轉換工具, 可同時替換兩岸不同的常用詞</td></tr><tr><td>提示範本 (prompt template)</td><td>事先寫好的固定指示, 使用時只要填入逐字稿等內容</td></tr><tr><td>上下文長度 (context length)</td><td>模型一次能處理的文字量上限; 逐字稿太長會超出</td></tr></tbody></table><p>完整詞彙見<a href="/lanai-handbook/ref/glossary">術語對照</a>.</p></div><h2 id="情境" tabindex="-1">情境 <a class="header-anchor" href="#情境" aria-label="Permalink to &quot;情境&quot;">​</a></h2><p>讀者是常需要寫會議記錄的人: 專案經理, 秘書, 或每週主持例會的主管. 原本的做法是邊開會邊打字, 或會後重聽錄音整理, 一小時的會議常要花上一小時以上整理. 雲端的會議轉錄服務能省下這段時間, 但內部會議常討論人事, 報價或客戶資料, 不一定適合上傳.</p><p>本範例分成兩段: 先把錄音轉成逐字稿, 再請模型從逐字稿整理出重點. 可以想成先請速記員打字, 再請助理整理成會議記錄; 最後由讀者這位主席確認內容無誤.</p><h2 id="需要的模組" tabindex="-1">需要的模組 <a class="header-anchor" href="#需要的模組" aria-label="Permalink to &quot;需要的模組&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模組</th><th>里程碑</th><th>在本範例的用途</th></tr></thead><tbody><tr><td><a href="/lanai-handbook/build/m0-foundation">M0 基礎環境</a></td><td>里程碑 1</td><td>單機即可; 錄音檔與逐字稿的保存與刪除規則</td></tr><tr><td><a href="/lanai-handbook/build/m1-inference">M1 推論伺服器</a></td><td>里程碑 1</td><td>以 Ollama (載入模型並提供 API 的推論伺服器) 執行對話模型, 負責整理摘要</td></tr><tr><td><a href="/lanai-handbook/build/m2-ui-proxy">M2 使用者介面與反向代理</a></td><td>里程碑 1</td><td>在 Open WebUI (瀏覽器上的對話介面) 使用固定的會議記錄提示範本</td></tr><tr><td>語音轉文字程式 (不屬於任何模組)</td><td>-</td><td>例如 whisper.cpp, 在本機把錄音轉成文字檔</td></tr></tbody></table><h2 id="流程" tabindex="-1">流程 <a class="header-anchor" href="#流程" aria-label="Permalink to &quot;流程&quot;">​</a></h2><p>錄音先轉成逐字稿, 必要時轉成台灣用字, 記錄者校對專有名詞後, 再交給對話模型依固定格式整理; 最後由記錄者核對並自己寄出. 下圖由上而下對應這五個步驟.</p>',12)),(e(),l(o,null,{default:a(()=>[h(i,{id:"mermaid-187",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%9C%83%E8%AD%B0%E9%8C%84%E9%9F%B3%3A%20%E6%89%8B%E6%A9%9F%E6%88%96%E9%9B%BB%E8%85%A6%E9%8C%84%E8%A3%BD%E7%9A%84%20m4a%2C%20mp3%3Cbr%2F%3E(%E9%8C%84%E9%9F%B3%E5%89%8D%E5%8F%96%E5%BE%97%E8%88%87%E6%9C%83%E8%80%85%E5%90%8C%E6%84%8F)%22%5D%20--%3E%7C%221.%20ffmpeg%20%E8%BD%89%E6%88%90%2016kHz%20%E5%96%AE%E8%81%B2%E9%81%93%2016-bit%20WAV%22%7C%20B%5B%22whisper.cpp%20(whisper-cli)%20%2B%20%E5%A4%9A%E8%AA%9E%20Whisper%20%E6%A8%A1%E5%9E%8B%3Cbr%2F%3E(%E6%9C%AC%E6%A9%9F%2C%20%E4%B8%8D%E9%9C%80%E7%B6%B2%E8%B7%AF)%22%5D%0A%20%20B%20--%3E%7C%222.%20%E8%BC%B8%E5%87%BA%E9%80%90%E5%AD%97%E7%A8%BF%20meeting.txt%22%7C%20C%5B%22OpenCC%20%E7%B0%A1%E7%B9%81%E8%BD%89%E6%8F%9B%20(%E8%BC%B8%E5%87%BA%E5%90%AB%E7%B0%A1%E9%AB%94%E5%AD%97%E6%99%82)%22%5D%0A%20%20C%20--%3E%20C2%5B%22meeting-tw.txt%22%5D%0A%20%20C2%20--%3E%7C%223.%20%E8%A8%98%E9%8C%84%E8%80%85%E5%BF%AB%E9%80%9F%E6%A0%A1%E5%B0%8D%E4%BA%BA%E5%90%8D%2C%20%E7%94%A2%E5%93%81%E5%90%8D%E8%88%87%E6%95%B8%E5%AD%97%22%7C%20D%5B%22%E7%80%8F%E8%A6%BD%E5%99%A8%20http%3A%2F%2F127.0.0.1%3A3000%22%5D%0A%20%20D%20--%3E%20E%5B%22Open%20WebUI%3A%20%2F%E6%9C%83%E8%AD%B0%E8%A8%98%E9%8C%84%20%E6%8F%90%E7%A4%BA%E7%AF%84%E6%9C%AC%22%5D%0A%20%20E%20--%3E%7C%224.%20%E9%80%90%E5%AD%97%E7%A8%BF%20%2B%20%E7%AF%84%E6%9C%AC%E9%80%81%E7%B5%A6%E5%B0%8D%E8%A9%B1%E6%A8%A1%E5%9E%8B%22%7C%20F%5B%22Ollama%20%E5%B0%8D%E8%A9%B1%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20F%20--%3E%20G%5B%22%E6%91%98%E8%A6%81%2C%20%E6%B1%BA%E8%AD%B0%2C%20%E5%BE%85%E8%BE%A6%E6%B8%85%E5%96%AE%20(%E6%A8%99%E8%A8%BB%E9%80%90%E5%AD%97%E7%A8%BF%E5%87%BA%E8%99%95)%22%5D%0A%20%20G%20--%3E%7C%225.%20%E8%A8%98%E9%8C%84%E8%80%85%E6%A0%B8%E5%B0%8D%E6%B1%BA%E8%AD%B0%2C%20%E8%B2%A0%E8%B2%AC%E4%BA%BA%2C%20%E6%9C%9F%E9%99%90%22%7C%20H%5B%22%E8%A8%98%E9%8C%84%E8%80%85%E8%87%AA%E5%B7%B1%E7%9A%84%E9%83%B5%E4%BB%B6%E8%BB%9F%E9%AB%94%22%5D%0A%20%20H%20--%3E%20I%5B%22%E5%AF%84%E7%B5%A6%E8%88%87%E6%9C%83%E8%80%85%22%5D%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=s(`<p>所有步驟都在讀者的電腦上完成; 寄送由讀者自己操作, 模型不經手寄信.</p><h2 id="設定要點" tabindex="-1">設定要點 <a class="header-anchor" href="#設定要點" aria-label="Permalink to &quot;設定要點&quot;">​</a></h2><p>以下指令依 whisper.cpp, OpenAI Whisper 與 OpenCC 的官方 README 整理, 未實機驗證.</p><p><strong>1. 選擇語音轉文字模型.</strong> whisper.cpp 是 Whisper 的 C/C++ 實作, 採 MIT 授權, 支援 Apple Silicon (Metal), NVIDIA (CUDA), AMD (ROCm), Vulkan 與純 CPU. OpenAI Whisper 的 README 說明程式碼與模型權重都以 MIT 授權釋出. 選模型時注意兩點:</p><ul><li>名稱有 <code>.en</code> 的是純英文模型, 中文會議要選多語模型 (例如 <code>small</code>, <code>medium</code>, <code>large-v3-turbo</code>).</li><li>whisper.cpp README 列出的大致需求: <code>small</code> 磁碟 466MiB, 記憶體約 852MB; <code>medium</code> 1.5GiB, 約 2.1GB; <code>large</code> 2.9GiB, 約 3.9GB. <code>large-v3-turbo</code> 的模型檔為 1.5GiB. OpenAI 說明 turbo 是 large-v3 的加速版本, 準確度略降.</li></ul><p><strong>2. 轉換與轉錄.</strong> 下列指令在終端機依序執行三件事: 下載轉錄模型, 把錄音轉成 whisper-cli 能讀的格式, 再輸出逐字稿.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#768390;"># 下載模型 (在 whisper.cpp 目錄中執行)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">sh</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> ./models/download-ggml-model.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> large-v3-turbo</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#768390;"># whisper-cli 目前只接受 16-bit WAV, 先用 ffmpeg 轉檔</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">ffmpeg</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> meeting.m4a</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> -ar</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> 16000</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> -ac</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> 1</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> -c:a</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> pcm_s16le</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> meeting.wav</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#768390;"># 指定中文, 輸出文字檔 meeting.txt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">./build/bin/whisper-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> models/ggml-large-v3-turbo.bin</span><span style="--shiki-light:#005CC5;--shiki-dark:#F47067;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;">  -f</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> meeting.wav</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> -l</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> zh</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> -otxt</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> -of</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> meeting</span></span></code></pre></div><p>whisper-cli 的 <code>-l</code> 預設為 <code>en</code>, 中文會議務必指定 <code>zh</code> (或 <code>auto</code> 自動偵測). 另有 <code>--prompt</code> 可提供初始提示, 例如放入常出現的人名與產品名; 效果因錄音而異, 請自行比較 (推論).</p><p><strong>3. 轉成台灣用字.</strong> 若逐字稿出現簡體字, 可用簡繁轉換工具 OpenCC (Apache 2.0) 的 <code>s2twp</code> 設定轉成台灣正體並替換台灣常用詞彙:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">opencc</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> s2twp.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> meeting.txt</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> meeting-tw.txt</span></span></code></pre></div><p><strong>4. 建立會議記錄提示範本.</strong> 在 Open WebUI 的 <strong>Workspace &gt; Prompts</strong> 建立範本, Command 設為 <code>/會議記錄</code> 這類好記的名稱 (避開內建指令名稱). 官方文件支援在範本中以兩層大括號定義輸入欄位, 寫法為「變數名稱 | 類型:required」, 類型包含 text, textarea, date 等, 使用範本時會跳出表單 (寫法見下方範例):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>以下是會議「{{title | text:required}}」的逐字稿, 會議日期為 {{meeting_date | date:required}}.</span></span>
<span class="line"><span>請用繁體中文整理成會議記錄, 格式如下:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>一, 會議摘要 (5 點以內)</span></span>
<span class="line"><span>二, 決議事項 (每點標出逐字稿中的原句)</span></span>
<span class="line"><span>三, 待辦清單 (表格: 事項, 負責人, 期限; 逐字稿沒說清楚的欄位填「未確認」)</span></span>
<span class="line"><span>四, 待釐清問題</span></span>
<span class="line"><span></span></span>
<span class="line"><span>規則: 只根據逐字稿整理, 不要推測沒有說出口的決定; 人名與數字照逐字稿原文.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>逐字稿:</span></span>
<span class="line"><span>{{transcript | textarea:required}}</span></span></code></pre></div><p><strong>5. 長逐字稿分段處理.</strong> Open WebUI 官方疑難排解頁指出, Ollama 在顯示記憶體小於 24GiB 時預設上下文只有 4096 token. 一小時會議的逐字稿通常超過這個長度 (推論). 做法有兩種: 依 M1.8 節調高上下文長度; 或把逐字稿依議程切成幾段, 每段先各自整理, 最後再請模型合併 (推論, 信心: 中).</p><p><strong>6. 可選: 介面內建的語音轉文字.</strong> Open WebUI 內建本機 Whisper (以另一套 Whisper 執行程式 faster_whisper 執行, <code>WHISPER_MODEL</code> 預設為 <code>base</code>, 可用 <code>WHISPER_LANGUAGE</code> 指定語言), 適合用麥克風口述. 是否支援直接上傳錄音檔, 官方文件未說明, 因此本頁以 whisper.cpp 處理錄音檔.</p><h2 id="驗收方式" tabindex="-1">驗收方式 <a class="header-anchor" href="#驗收方式" aria-label="Permalink to &quot;驗收方式&quot;">​</a></h2><p>找 3 場已經有人工會議記錄的過往會議 (例如 30 分鐘, 60 分鐘, 中英夾雜各一場), 依下列步驟比對:</p><ol><li><strong>逐字稿抽查</strong>: 每場隨機抽 3 段, 每段約 1 分鐘, 對照錄音逐字核對, 記下人名, 數字與專有名詞的錯誤數. 錯誤集中在特定名詞時, 試著加上 <code>--prompt</code> 或換較大的模型.</li><li><strong>決議與待辦比對</strong>: 以人工記錄為標準, 計算模型整理的決議與待辦有幾項漏列, 幾項多出 (人工記錄沒有的事項). 多出的事項要特別檢查是不是模型推測出來的.</li><li><strong>負責人與期限</strong>: 逐項核對待辦清單的負責人與期限; 逐字稿沒有明講的欄位, 應該標為「未確認」, 而不是填入猜測值.</li><li><strong>出處檢查</strong>: 決議事項附的原句, 都能在逐字稿中找到.</li><li><strong>處理時間</strong>: 記錄轉錄與整理各花多少時間, 作為之後換硬體或換模型的比較基準.</li></ol><p>把這 3 場的逐字稿與比對結果保存為測試資料 (見 M6.1 節), 之後換模型時重跑.</p><h2 id="風險與限制" tabindex="-1">風險與限制 <a class="header-anchor" href="#風險與限制" aria-label="Permalink to &quot;風險與限制&quot;">​</a></h2><table tabindex="0"><thead><tr><th>風險</th><th>影響</th><th>因應方式</th></tr></thead><tbody><tr><td>錄音與逐字稿含敏感內容</td><td>檔案留在電腦, 備份與 Open WebUI 的對話紀錄中</td><td>錄音前取得與會者同意並依公司規定處理; 會議記錄寄出後刪除錄音與中間檔, 定期清理對話紀錄</td></tr><tr><td>轉錄錯誤</td><td>人名, 數字, 中英夾雜的術語特別容易錯, 錯誤會延續到摘要</td><td>校對專有名詞與數字; 重要會議以錄音為準</td></tr><tr><td>模型漏列或捏造決議</td><td>與會者依錯誤的會議記錄行動</td><td>提示範本要求附原句; 記錄者逐項核對後才寄出</td></tr><tr><td>模型猜測待辦的負責人或期限</td><td>責任歸屬錯誤</td><td>範本要求未明說者填「未確認」; 寄出前由主席確認</td></tr><tr><td>上下文不足導致後半段遺漏</td><td>會議後段的決議沒有出現在摘要中</td><td>調高上下文長度或分段整理; 驗收時特別檢查最後 10 分鐘的內容</td></tr><tr><td>說話者無法區分</td><td>逐字稿看不出誰說了什麼, 影響負責人判斷</td><td>whisper.cpp 的說話者區分功能 (tinydiarize) 標為實驗功能; 必要時由記錄者補上說話者</td></tr></tbody></table><p>需要人工確認的步驟: 轉錄後校對專有名詞與數字; 寄出前核對決議, 負責人與期限.</p><h2 id="參考來源" tabindex="-1">參考來源 <a class="header-anchor" href="#參考來源" aria-label="Permalink to &quot;參考來源&quot;">​</a></h2><ul><li><a href="https://github.com/ggml-org/whisper.cpp" target="_blank" rel="noreferrer">whisper.cpp GitHub 儲存庫 (README)</a></li><li><a href="https://raw.githubusercontent.com/ggml-org/whisper.cpp/master/examples/cli/README.md" target="_blank" rel="noreferrer">whisper.cpp: whisper-cli 參數說明 (examples/cli/README.md)</a></li><li><a href="https://raw.githubusercontent.com/ggml-org/whisper.cpp/master/models/README.md" target="_blank" rel="noreferrer">whisper.cpp: 模型下載說明 (models/README.md)</a></li><li><a href="https://raw.githubusercontent.com/openai/whisper/main/README.md" target="_blank" rel="noreferrer">OpenAI Whisper README (模型大小與授權)</a></li><li><a href="https://raw.githubusercontent.com/BYVoid/OpenCC/master/README.md" target="_blank" rel="noreferrer">OpenCC README (s2twp 設定與授權)</a></li><li><a href="https://docs.openwebui.com/features/workspace/prompts" target="_blank" rel="noreferrer">Open WebUI 文件: Prompts</a></li><li><a href="https://docs.openwebui.com/features/chat-conversations/audio/speech-to-text/openai-stt-integration" target="_blank" rel="noreferrer">Open WebUI 文件: Speech-to-Text</a></li><li><a href="https://docs.openwebui.com/reference/env-configuration" target="_blank" rel="noreferrer">Open WebUI 文件: Environment Variable Configuration (WHISPER_MODEL)</a></li><li><a href="https://docs.openwebui.com/troubleshooting/rag" target="_blank" rel="noreferrer">Open WebUI 文件: RAG 疑難排解 (Ollama 預設上下文)</a></li><li>站內: <a href="/lanai-handbook/build/m1-inference">M1 推論伺服器</a></li><li>文中的類比 (速記員與助理): 整理者所寫, 無外部來源, 不應當作技術定義引用.</li></ul>`,23))])}const F=n(E,[["render",c]]);export{b as __pageData,F as default};
